{
  "findings": [
    {
      "check_id": "CKV_AZURE_70",
      "title": "Ensure that Function apps is only accessible over HTTPS",
      "resource": "azurerm_function_app.changeme_simple_function_app",
      "severity": "MEDIUM",
      "explanation": "The resource does not explicitly enforce HTTPS-only traffic. By default, Azure Function Apps may allow HTTP requests unless `https_only` is set to true, exposing data in transit."
    },
    {
      "check_id": "CKV_AZURE_67",
      "title": "Ensure that 'HTTP Version' is the latest, if used to run the Function app",
      "resource": "azurerm_function_app.changeme_simple_function_app",
      "severity": "MEDIUM",
      "explanation": "The resource lacks a `site_config` block specifying `http2_enabled = true`. Enabling HTTP/2 improves performance and security by supporting modern TLS features and multiplexing."
    },
    {
      "check_id": "CKV_AZURE_56",
      "title": "Ensure that function apps enables Authentication",
      "resource": "azurerm_function_app.changeme_simple_function_app",
      "severity": "MEDIUM",
      "explanation": "The resource does not configure an `auth_settings` block. Without authentication enabled, the function app endpoints are publicly accessible without identity verification, increasing the risk of unauthorized access."
    }
  ],
  "patched_code": "resource \"azurerm_function_app\" \"changeme_simple_function_app\" {\n  name                       = \"changeme-simple-function-app-name\"\n  location                   = azurerm_resource_group.changeme_simple_function_app_resource_group.location\n  resource_group_name        = azurerm_resource_group.changeme_simple_function_app_resource_group.name\n  app_service_plan_id        = azurerm_app_service_plan.changeme_simple_function_app_app_service_plan.id\n  storage_account_name       = azurerm_storage_account.changeme_simple_function_app_storage_account.name\n  storage_account_access_key = azurerm_storage_account.changeme_simple_function_app_storage_account.primary_access_key\n\n  https_only = true\n\n  site_config {\n    http2_enabled = true\n  }\n\n  auth_settings {\n    enabled         = true\n    unauthenticated_client_action = \"RedirectToLoginPage\"\n    token_store_enabled = true\n    default_provider = \"AzureActiveDirectory\"\n\n    active_directory {\n      client_id     = \"REPLACE_WITH_CLIENT_ID\"\n      tenant_id     = \"REPLACE_WITH_TENANT_ID\"\n      allowed_audiences = [\"REPLACE_WITH_AUDIENCE\"]\n    }\n  }\n}",
  "fix_summary": "Added `https_only = true` to enforce HTTPS traffic. Added `site_config` with `http2_enabled = true` to ensure modern HTTP version support. Added `auth_settings` block to enable authentication via Azure Active Directory, requiring valid tokens for access."
}
